
const WORDS=[{"id": 0, "w": "引用", "p": "yǐnyòng", "t": "动词", "m": "trích dẫn", "coll": "引用原文、引用资料", "s": "写论文时，引用别人的观点需要注明来源。"}, {"id": 1, "w": "截至", "p": "jiézhì", "t": "介词／动词", "m": "tính đến, cho đến (một thời điểm)", "coll": "截至目前、截至月底", "s": "截至本周五，已有三十位同学报名参加这次比赛。"}, {"id": 2, "w": "力争", "p": "lìzhēng", "t": "动词", "m": "cố gắng, phấn đấu", "coll": "力争上游、力争完成", "s": "团队成员分工合作，力争在月底之前完成全部任务。"}, {"id": 3, "w": "亚军", "p": "yàjūn", "t": "名词", "m": "á quân, người (đội) đứng thứ nhì trong một cuộc đua/thi đấu", "coll": "获得亚军、男子单打亚军", "s": "经过激烈角逐，他获得了男子单打亚军。"}, {"id": 4, "w": "季军", "p": "jìjūn", "t": "名词", "m": "người (đội) đứng thứ ba trong một cuộc đua/thi đấu", "coll": "获得季军、季军争夺战", "s": "这支年轻的队伍凭借出色的配合，获得了本届比赛的季军。"}, {"id": 5, "w": "极限", "p": "jíxiàn", "t": "名词", "m": "giới hạn cuối cùng, cực hạn", "coll": "挑战极限、达到极限", "s": "这部纪录片讲述了运动员不断挑战自身极限的故事。"}, {"id": 6, "w": "狭窄", "p": "xiázhǎi", "t": "形容词", "m": "chật hẹp, eo hẹp", "coll": "道路狭窄、空间狭窄", "s": "这条小巷十分狭窄，只能容纳两个人并肩通过。"}, {"id": 7, "w": "任性", "p": "rènxìng", "t": "形容词", "m": "bướng bỉnh, tùy hứng, chỉ làm theo ý mình", "coll": "有些任性、任性的行为", "s": "她逐渐明白，不能因为任性就忽略别人的感受。"}, {"id": 8, "w": "田径", "p": "tiánjìng", "t": "名词", "m": "môn điền kinh", "coll": "田径比赛、田径运动员", "s": "学校每年都会举行一次田径比赛。"}, {"id": 9, "w": "选手", "p": "xuǎnshǒu", "t": "名词", "m": "tuyển thủ", "coll": "参赛选手、优秀选手", "s": "来自不同地区的选手正在赛场上进行最后的准备。"}, {"id": 10, "w": "同胞", "p": "tóngbāo", "t": "名词", "m": "đồng bào", "coll": "海外同胞、各族同胞", "s": "这场文化活动吸引了许多海外同胞参加。"}, {"id": 11, "w": "直播", "p": "zhíbō", "t": "动词／名词", "m": "phát sóng trực tiếp; chương trình phát trực tiếp", "coll": "现场直播、直播比赛", "s": "因为无法到场，他们通过网络观看了比赛的现场直播。"}, {"id": 12, "w": "旗帜", "p": "qízhì", "t": "名词", "m": "lá cờ; ngọn cờ, tấm gương tiêu biểu", "coll": "一面旗帜、旗帜飘扬", "s": "运动员们举着一面旗帜，缓缓走进开幕式现场。"}, {"id": 13, "w": "领先", "p": "lǐngxiān", "t": "动词", "m": "dẫn đầu, đi đầu", "coll": "暂时领先、保持领先", "s": "比赛进行到最后一圈时，她仍然保持领先。"}, {"id": 14, "w": "分解", "p": "fēnjiě", "t": "动词", "m": "phân tích, phân giải, tan rã", "coll": "分解动作、分解任务", "s": "为了方便初学者，老师把整套动作分解成几个简单的步骤。"}, {"id": 15, "w": "公式", "p": "gōngshì", "t": "名词", "m": "công thức", "coll": "计算公式、运用公式", "s": "理解原理以后，学生再尝试运用公式解决问题。"}, {"id": 16, "w": "精密", "p": "jīngmì", "t": "形容词", "m": "tỉ mỉ chính xác", "coll": "精密仪器、设计精密", "s": "工作人员利用精密仪器测量了零件的尺寸。"}, {"id": 17, "w": "悬殊", "p": "xuánshū", "t": "形容词", "m": "khác xa nhau, chênh lệch xa", "coll": "实力悬殊、差距悬殊", "s": "虽然双方实力悬殊，这支年轻的队伍仍然认真对待比赛。"}, {"id": 18, "w": "迷信", "p": "míxìn", "t": "动词／名词", "m": "mê tín, tin tưởng mù quáng; sự mê tín", "coll": "破除迷信、不能迷信", "s": "学习别人的经验时，不能迷信权威，也要结合自己的实际情况。"}, {"id": 19, "w": "舆论", "p": "yúlùn", "t": "名词", "m": "dư luận", "coll": "社会舆论、舆论关注", "s": "这项决定引起了社会舆论的广泛关注。"}, {"id": 20, "w": "自发", "p": "zìfā", "t": "形容词", "m": "tự phát, tự ý", "coll": "自发组织、自发参与", "s": "附近居民自发组织起来，一起清理公园里的垃圾。"}, {"id": 21, "w": "掀起", "p": "xiānqǐ", "t": "动词", "m": "nhấc, lật lên; dấy lên (làn sóng, phong trào)", "coll": "掀起热潮、掀起波浪", "s": "这次展览在校园里掀起了学习传统文化的热潮。"}, {"id": 22, "w": "空洞", "p": "kōngdòng", "t": "形容词", "m": "trống rỗng, suông", "coll": "空洞的口号、内容空洞", "s": "这篇文章只有空洞的口号，缺少具体的例子和分析。"}, {"id": 23, "w": "制约", "p": "zhìyuē", "t": "动词", "m": "kìm hãm, hạn chế", "coll": "制约发展、相互制约", "s": "交通不便曾经制约了这个地区的发展。"}, {"id": 24, "w": "原理", "p": "yuánlǐ", "t": "名词", "m": "nguyên lý", "coll": "基本原理、工作原理", "s": "老师用一个简单的实验解释了机器的工作原理。"}, {"id": 25, "w": "冷酷", "p": "lěngkù", "t": "形容词", "m": "cay nghiệt, ác nghiệt, nhẫn tâm", "coll": "态度冷酷、冷酷无情", "s": "小说中的人物外表冷酷，内心却十分关心家人。"}, {"id": 26, "w": "动员", "p": "dòngyuán", "t": "动词", "m": "huy động, động viên", "coll": "动员群众、动员大家", "s": "负责人动员大家利用周末的时间，共同完成场地整理工作。"}, {"id": 27, "w": "牵扯", "p": "qiānchě", "t": "动词", "m": "liên quan đến, dính líu, kéo vào", "coll": "牵扯其中、牵扯到利益", "s": "这个问题牵扯到多个部门的工作，需要共同协商。"}, {"id": 28, "w": "胸膛", "p": "xiōngtáng", "t": "名词", "m": "ngực", "coll": "挺起胸膛、宽阔的胸膛", "s": "听到自己的名字，他挺起胸膛，自信地走上领奖台。"}, {"id": 29, "w": "管辖", "p": "guǎnxiá", "t": "动词", "m": "quản lý, cai quản", "coll": "管辖范围、归谁管辖", "s": "这张地图标明了该管理机构的管辖范围。"}, {"id": 30, "w": "故障", "p": "gùzhàng", "t": "名词", "m": "sự trục trặc, sự cố", "coll": "发生故障、排除故障", "s": "设备突然发生故障，技术人员立即开始检查。"}, {"id": 31, "w": "严禁", "p": "yánjìn", "t": "动词", "m": "nghiêm cấm", "coll": "严禁吸烟、严禁入内", "s": "展厅入口处挂着严禁吸烟的提示牌。"}, {"id": 32, "w": "猝死", "p": "cùsǐ", "t": "动词／名词", "m": "đột tử; trường hợp đột tử", "coll": "猝死案例、猝死研究", "s": "小说中，这名角色突然猝死，其他人都感到震惊。"}, {"id": 33, "w": "正规", "p": "zhèngguī", "t": "形容词", "m": "chính quy, đúng chuẩn mực", "coll": "正规学校、正规渠道", "s": "购买重要资料时，她总是选择正规的出版渠道。"}, {"id": 34, "w": "演习", "p": "yǎnxí", "t": "动词", "m": "diễn tập, tập luyện", "coll": "消防演习、组织演习", "s": "学校组织了一次消防演习，帮助师生熟悉疏散路线。"}, {"id": 35, "w": "弹性", "p": "tánxìng", "t": "名词", "m": "tính co giãn, tính đàn hồi", "coll": "富有弹性、弹性材料", "s": "这种材料很有弹性，拉长以后还能恢复原状。"}, {"id": 36, "w": "竞赛", "p": "jìngsài", "t": "动词／名词", "m": "thi đấu, thi đua; cuộc thi", "coll": "知识竞赛、参加竞赛", "s": "同学们组成小组，参加了学校的知识竞赛。"}, {"id": 37, "w": "优先", "p": "yōuxiān", "t": "动词", "m": "ưu tiên", "coll": "优先考虑、优先安排", "s": "安排工作时，应该优先考虑那些紧急而重要的任务。"}, {"id": 38, "w": "选拔", "p": "xuǎnbá", "t": "动词", "m": "tuyển chọn", "coll": "选拔人才、选拔队员", "s": "学校通过公开比赛选拔了参加决赛的队员。"}, {"id": 39, "w": "资产", "p": "zīchǎn", "t": "名词", "m": "tài sản, của cải", "coll": "固定资产、资产管理", "s": "这份案例介绍了一家企业资产管理方面的经验。"}, {"id": 40, "w": "得天独厚", "p": "détiān dúhòu", "t": "成语", "m": "được thiên nhiên ưu đãi, có điều kiện thuận lợi đặc biệt", "coll": "得天独厚的条件、得天独厚的优势", "s": "这里拥有得天独厚的自然条件，适合开展生态旅游。"}, {"id": 41, "w": "作风", "p": "zuòfēng", "t": "名词", "m": "tác phong, phong cách", "coll": "工作作风、严谨作风", "s": "他认真负责的工作作风给同事们留下了深刻的印象。"}, {"id": 42, "w": "顽强", "p": "wánqiáng", "t": "形容词", "m": "ngoan cường", "coll": "顽强的意志、顽强拼搏", "s": "面对强大的对手，队员们依然顽强拼搏，坚持到了最后。"}, {"id": 43, "w": "志气", "p": "zhìqì", "t": "名词", "m": "chí khí, nhuệ khí", "coll": "有志气、胸怀志气", "s": "这位年轻人很有志气，希望通过努力改变自己的生活。"}, {"id": 44, "w": "屈服", "p": "qūfú", "t": "动词", "m": "khuất phục, đầu hàng", "coll": "向困难屈服、不肯屈服", "s": "即使遭遇挫折，她也不肯向困难屈服。"}, {"id": 45, "w": "相辅相成", "p": "xiāngfǔ xiāngchéng", "t": "成语", "m": "kết hợp và hỗ trợ lẫn nhau", "coll": "相辅相成、两者相辅相成", "s": "理论学习与实践探索相辅相成，缺一不可。"}];
